  "tower.anchors.lede": "Kila uchukuaji, ufikishaji, lakiri, uchanganuzi na ripoti ya uharibifu huwekewa alama ya utambulisho ndani ya mnyororo mmoja. Mara moja kwa siku kiungo chake kipya zaidi hutumwa kwa anwani ya mkaguzi wa hesabu, mahali ambapo hatuwezi kukibadilisha. Ikiwa chochote hadi kiungo hicho kitabadilishwa baadaye, mnyororo hautoi tena kiungo kilekile, na nakala ya mkaguzi inaonyesha hilo.",
