  "tower.observations.lede": "Shuhuda za moja kwa moja kutoka kwa madereva na mawakala kwenye kaunta: hati ipi, wapi, siku gani. Sheria zilizo juu ni zetu kuzitunza; hizi ni mchana wa mtu fulani, na zinaonyeshwa hivyo.",
