  "tower.papers.transitTitle": "Nani anaweza kubeba bidhaa ambazo hazijatolewa forodhani",
  "tower.papers.transitLede": "Kontena linalotolewa forodhani bara linasafiri kutoka gatini chini ya dhamana ya forodha, na mzigo unatolewa tu kwa msafirishaji mwenye kibali cha usafirishaji wa kupita katika nchi hiyo. Kampuni ya magari huhifadhi leseni zake za udereva kwenye programu ya Fleet; kibali hiki hakina ofisi nyingine ila yetu, na kinapoisha muda msafirishaji anaacha tu kupewa kazi chini ya dhamana ya forodha.",
  "tower.papers.transitBasis": "Kinarekodiwa kama msafirishaji anavyokieleza, dhidi ya yeyote aliyekiandika. Tunakagua kwamba kipo na bado kinatumika; hatukithibitishi kwa mamlaka iliyokitoa.",
