  "tower.market.title": "Soko linavyokwenda",
  "tower.market.lede": "Kile watumaji wa mizigo walichoomba, dhidi ya kile kampuni za magari zilichochukua kweli — siku kwa siku, mizigo inasubiri kwa muda gani, bei zilizojadiliwa zilikubaliwa kwa kiasi gani, na njia zipi zimetulia.",
  "tower.market.caveatT": "Hakuna anayeripoti chochote kati ya haya.",
  "tower.market.caveat": "Kila takwimu hapa inatokana na nyakati ambazo mzigo tayari unazo. Kampuni ya magari inayopunguza uwezo wake haiwasilishi taarifa — inaacha tu kuchukua mizigo — kwa hiyo mistari hii inajisogeza yenyewe ndani ya siku moja, na hiyo ndiyo sababu pekee inayofanya iweze kuaminika katika soko ambalo watu wana shughuli nyingi na fomu hazijazwi.",
  "tower.market.range": "{n, plural, one {siku #} other {siku #}}",
  "tower.market.pickRange": "Kusoma kwa muda gani nyuma",
  "tower.nav.movers": "Wasafirishaji",
  "tower.movers.title": "Wanaosafirisha mizigo",
  "tower.movers.lede": "Rekodi ileile iliyo kwenye ukurasa wao wa umma, pamoja na mambo mawili ambayo ukurasa huo hauna: kwa nini kila mzigo ulirudishwa, na dereva yupi aliurudisha. Wamepangwa kwa jinsi walivyo na shughuli nyingi — kamwe si kwa jinsi walivyofanya vizuri.",
  "tower.movers.count": "kampuni za magari: {n}",
  "tower.movers.loading": "Inasoma rekodi…",
  "tower.movers.noneTitle": "Bado hakuna kampuni ya magari iliyochukua mzigo",
  "tower.movers.noneBody": "Rekodi inaonekana hapa mara ya kwanza mtu anapochukua kazi kutoka kwenye ubao.",
  "tower.movers.col.fleet": "Kampuni ya magari",
