  "tower.movers.col.driver": "Dereva",
  "tower.movers.drivers": "madereva: {n}",
  "tower.movers.thin": "ni wachache mno kupewa kiwango (inahitaji {n})",
  "tower.movers.rates": "ilibakiza {kept}% · ilifikisha {delivered}%",
  "tower.movers.tight": "ilichukua {kept} ambayo hakuna mwingine angechukua, ilifikisha {delivered}",
  "tower.movers.why": "Kwa nini",
  "tower.movers.handBacksTitle": "Kwa nini mizigo ilirudishwa",
  "tower.movers.handBacksWhy": "Haipo kwenye ukurasa wao wa umma, na hilo ni kwa makusudi. Dereva ambaye muda wake wa kupumzika ulifika amefanya jambo sahihi kwa kurudisha mzigo — kuchapisha sababu kungeadhibu matumizi ya uaminifu ya sheria tuliyoiandika, na matokeo yake yangekuwa madereva wanaoendesha wakiwa wamechoka badala yake. IDADI ni ya umma; sababu ni ya yeyote anayeshughulikia lalamiko.",
  "tower.movers.noHandBacks": "Hawajawahi kurudisha mzigo.",
  "tower.movers.perDriverTitle": "Kwa dereva",
  "tower.movers.perDriverWhy": "Majina yanaonekana hapa na si mahali popote pa umma. Dereva anayeweza kutambuliwa kuwa ndiye aliyerudisha mzigo ni dereva anayeacha kuchukua mizigo migumu.",
