  "tower.pilot.title": "Mradi wa majaribio, wiki kwa wiki",
  "tower.pilot.lede": "Nambari nne ambazo mwongozo (compendium) unatumia kupima mradi wa majaribio, kila wiki dhidi ya lengo lake. Wiki iliyokwisha inagandishwa na haihesabiwi tena; wiki hii ni hadi sasa. Wiki zinaanza Jumapili hadi Jumamosi, UTC.",
