  "tower.pilot.lossSub": "{lost} vimepotea · {damaged} vimeharibika · kati ya {takenIn} vilivyopokelewa",
  "tower.pilot.takeInSub": "kipimo cha kati cha {n} vilivyopimwa muda · kimoja kati ya kumi cha polepole zaidi {p90}",
