  "tower.pilot.retentionSub": "{active} kati ya {original}",
  "tower.pilot.noPilotYet": "bado hakuna kifurushi kilichopokelewa",
  "tower.pilot.seconds": "{n} s",
  "tower.pilot.howTitle": "Jinsi kila kimoja kinavyohesabiwa",
  "tower.pilot.how.handshake": "Makabidhiano: kati ya vifurushi vilivyopaswa kupakiwa kwenye basi wakati wa makabidhiano kaunta, sehemu ambayo duka lilichanganua kuingia humo. Kimoja kilichoachwa kinahesabiwa dhidi yake, kwa sababu yoyote ile. Lengo {target}; chini ya {warn} kunahitaji jina la mtu anayehusika.",
  "tower.pilot.how.loss": "Vilivyopotea au kuharibika: vifurushi vilivyotangazwa kupotea wiki hiyo na havikupatikana kufikia wakati ilipogandishwa, na matatizo yaliyoripotiwa kwenye vifurushi wiki hiyo, kwa kila kifurushi kilichopokelewa wiki hiyo. Lengo chini ya {target}; juu ya {warn} kunahitaji jina la mtu anayehusika.",
  "tower.pilot.how.takeIn": "Muda wa kupokea: katikati ya nyakati ambazo programu ya maduka ilipima, kuanzia mguso wa kwanza wa kupokea hadi kifurushi kupokelewa. Zaidi ya dakika 15 ni kukatizwa, si polepole, na hakuhesabiwi. Lengo chini ya {target} s; juu ya {warn} s kunahitaji jina la mtu anayehusika.",
  "tower.pilot.how.retention": "Maduka ya awali yanayofanya kazi: kati ya maduka yaliyofanya kazi kwenye kaunta katika wiki ya kwanza ya mradi wa majaribio, sehemu iliyofanya kazi wiki hii. Inapimwa kuanzia wiki ya {week}, dhidi ya {target}.",
  "tower.pilot.how.frozen": "Makabidhiano na nyakati za kupokea zinahesabiwa kuanzia 18 Oktoba 2026, zilipoanza kuhifadhiwa; wiki za kabla ya hapo hazionyeshi nambari kwa ajili yake.",
  "tower.nav.claims": "Madai ya uharibifu",
  "tower.nav.disposal": "Vinasubiri kuondolewa",
  "tower.nav.approvals": "Kujiunga na mtandao",
  "tower.nav.papers": "Hati",
  "tower.nav.reports": "Ujumbe ulioripotiwa",
  "tower.reports.title": "Ripoti za madai ya uharibifu",
  "tower.reports.lede": "Kila tatizo lililoripotiwa, la karibuni kwanza. Wafanyakazi hawaamui chochote hapa: ripoti ilitengenezwa pale pale tatizo liliporipotiwa, kutokana na rekodi ilivyokuwa, na yule inayemhusu anaikabidhi kwa kampuni yake mwenyewe ya bima.",
  "tower.reports.caveatT": "Hakuna kitu hapa kinachoondoa chochote.",
  "tower.reports.caveat": "Mazungumzo hayahaririwi wala hayafutwi kamwe, ili yaweze kuonyeshwa ikiwa watu wawili hawakubaliani. Mshughulikie mtu, si ujumbe: kinachojalisha ni mwenendo unaojitokeza kwa waripoti kadhaa.",
  "tower.reports.count": "{n} zimetengenezwa",
  "tower.reports.emptyTitle": "Hakuna tatizo lililoripotiwa",
  "tower.reports.emptyBody": "Ripoti inaonekana hapa pale pale mtu anaporipoti tatizo, kwenye kaunta au kutoka kwenye programu yake.",
  "tower.reports.col.reason": "Sababu",
  "tower.reports.col.message": "Kilichosemwa",
  "tower.reports.col.from": "Kutoka",
  "tower.reports.col.reporters": "Imeripotiwa na",
  "tower.reports.col.when": "Iliripotiwa",
  "tower.reports.reason.scam": "Inaonekana kuwa utapeli",
  "tower.reports.reason.abuse": "Matusi",
  "tower.reports.reason.spam": "Barua taka",
  "tower.reports.disputeCount": "Ripoti {n} za mzozo zimeshirikiwa",
  "tower.reports.disputeLede": "Mhusika alichagua ujumbe huu na akaushiriki. Nakala imegandishwa na ina alama ya utambulisho, kwa hiyo haiwezi kubadilika baada ya kushirikiwa. Upande mwingine uliambiwa kwenye mazungumzo.",
  "tower.reports.disputeEmpty": "Hakuna ripoti za mzozo zilizoshirikiwa.",
