  "tower.reports.sharedBy.poster": "Aliyeweka mzigo",
  "tower.reports.sharedBy.asker": "Aliyeuliza",
  "tower.reports.fromPoster": "Aliyeweka",
  "tower.reports.fromAsker": "Aliyeuliza",
