  "tower.companies.title": "Kampuni, kando kwa kando",
  "tower.companies.lede": "Kila moja ni kampuni tofauti yenye sarafu yake, usajili wake wa kodi na hesabu zake. Hapa ndipo mahali pekee zinapoweza kusomwa dhidi ya nyingine.",
  "tower.companies.caveatLead": "Hakuna kinachojumlishwa hapa.",
  "tower.companies.caveat": "Kampuni hizi zinalipana kwa sarafu tofauti, na jumla ya zote ingekuwa nambari isiyo sahihi kwa namna ambayo hakuna anayeweza kuiona. Kila safu inabaki katika pesa zake.",
  "tower.companies.loading": "Inasoma kampuni…",
  "tower.companies.groupCharges": "Kampuni mama haitozi chochote: si muuzaji rasmi popote na kamwe si mhusika katika muamala wa mteja. Inapata ada yake ya leseni kutoka kwa kampuni dada.",
  "tower.companies.noPricing": "Haikuweza kusoma kile kampuni hii inachotoza.",
  "tower.companies.noBooks": "Haikuweza kusoma hesabu za kampuni hii. Inaonyeshwa kama haipo badala ya sifuri — salio la sifuri na swali lisilojibiwa vinaonekana sawa na vinamaanisha mambo yanayopingana.",
  "tower.companies.groupBooks": "Hailipi kwa sarafu yake yenyewe, kwa hiyo hakuna cha kushikilia dhidi ya inachodaiwa — utoshelevu ni swali ambalo kampuni inayofanya biashara tu inaweza kuulizwa. Hesabu zake bado lazima zilingane, na zinalingana.",
