  "tower.companies.createLede": "Kampuni yetu au mshirika wa ndani inaanza kama rasimu, na rasimu haiwezi kufanya chochote. Inawashwa tu rekodi yake inapokamilika, hati zake zimethibitishwa na mtu wa pili, na watu wawili wanaidhinisha nchi yake ifikie kiwango hicho.",
