  "tower.companies.expiringTitleOwn": "Leseni na sera zako zinazokaribia kuisha muda",
  "tower.companies.expiringWhatToDo": "Huisha kila moja kwa aliyeitoa, kisha fungua rekodi ya kampuni na chini ya Leseni au Bima bonyeza “Badilisha, pamoja na hati yake”: weka tarehe mpya na uambatishe hati iliyohuishwa. Inahesabika kuanzia wakati huo. Wasimamizi wake wanatumiwa barua pepe siku 60, 30, 14, 7 na 1 kabla, na siku hati inapoisha muda.",
