  "tower.company.create.hasSister": "Nchi hiyo tayari ina kampuni yetu.",
  "tower.company.title": "Rekodi ya kampuni",
  "tower.company.ledeOwn": "Rekodi ya kampuni yako ni yako kuitunza. Maelezo yake ya kisheria, anwani, wamiliki, nambari za kodi na kile nchi inachodai: badilisha na uhifadhi. Leseni, sera ya bima, akaunti ya benki au anayeweza kutia sahihi inabadilika moja moja, pamoja na hati iliyo nyuma yake, na inahesabika kuanzia wakati huo. Wasimamizi wenzako, na kampuni iliyo juu ya yako, wanatumiwa barua pepe kwa kila mabadiliko kama hayo.",
  "tower.company.ledeDraft": "Kampuni yako bado haijawashwa. Hadi itakapowashwa, wafanyakazi wa SeeBuyGet wanaingiza rekodi yake na mtu wa pili anathibitisha kila hati. Weka hati zako kwenye rekodi chini ya Hati. Ikishawashwa, rekodi ni yako kuitunza.",
  "tower.company.ledeTheirs": "Kampuni hii imewashwa na inatunza rekodi yake yenyewe: wasimamizi wake ndio wanaoibadilisha, kila leseni, sera, akaunti ya benki na mtia sahihi pamoja na hati iliyo nyuma yake. Wewe unaisoma.",
  "tower.company.lede": "Kila kitu kinachofanya kampuni iwe halisi — muundo wake wa kisheria, usajili, watu wanaoweza kutia sahihi, wamiliki wake, nambari za kodi, benki, leseni, bima na hati zilizo nyuma yake. Vinaingizwa hapa, kutoka upande wa mtandao, kabla nchi yake haijawashwa.",
