  "tower.company.fold.switchedOff": "Haiwezi tena {list}",
  "tower.company.runningOut.own": "Huisha kila moja kwa aliyeitoa, kisha chini ya Leseni au Bima hapa chini bonyeza “Badilisha, pamoja na hati yake”: weka tarehe mpya na uambatishe hati iliyohuishwa. Inahesabika kuanzia wakati huo. Wasimamizi wako wanatumiwa barua pepe siku 60, 30, 14, 7 na 1 kabla, na siku hati inapoisha muda.",
  "tower.company.runningOut.ownDraft": "Huisha kila moja kwa aliyeitoa, kisha weka hati iliyohuishwa kwenye rekodi chini ya Hati hapa chini. Hadi kampuni yako itakapowashwa, wafanyakazi wa SeeBuyGet wanaingiza tarehe mpya.",
  "tower.company.runningOut.staff": "Kampuni inahuisha hati zake yenyewe: mmoja wa wasimamizi wake anaingiza tarehe mpya pamoja na hati iliyohuishwa iliyoambatishwa, na inahesabika mara moja. Wanatumiwa barua pepe siku 60, 30, 14, 7 na 1 kabla, na siku hati inapoisha muda.",
  "tower.company.runningOut.staffDraft": "Bado haijawashwa, kwa hiyo rekodi yake ni yako kuiingiza: hati iliyohuishwa ikishakuwa kwenye rekodi chini ya Hati na kuthibitishwa, ingiza tarehe yake mpya chini ya Leseni au Bima hapa chini.",
  "tower.company.declare.hint": "Kila kimoja kati ya hivi kinabadilika moja moja, pamoja na hati iliyo nyuma yake. Kinahesabika kuanzia wakati huo, na wasimamizi wenzako na kampuni iliyo juu ya yako wanaambiwa.",
