  "tower.paperReport.title": "Hati zilizoripotiwa",
  "tower.paperReport.lede": "Mtu aliyeingia na aliyeunganishwa na kampuni amesema kwamba mojawapo ya hati zake si sahihi, na ameambatisha kinachoonyesha hivyo. Hati inaendelea kuhesabika wakati unaangalia. Mmoja wenu anaweza kutupilia mbali ripoti, pamoja na sababu. Kubatilisha hati kunahitaji wawili wenu — mmoja anapendekeza, wa pili anaidhinisha — na si kabla kampuni haijajibu au siku zake saba kuisha.",
