  "tower.custodyCaps.none": "hakuna kikomo",
  "tower.custodyCaps.hint": "Maduka mapya hushika vifurushi vingapi, na mwendeshaji huru mpya hubeba vingapi, kwa wakati mmoja. Kila kikomo huongezeka kwa moja kwa kila kifurushi kinachokabidhiwa kwa mwingine, na huondolewa baada ya idadi uliyoweka. Acha visanduku vyote viwili tupu ili usiweke kikomo. Madereva wa kampuni ya magari hawawekewi kikomo hapa: kampuni yao ya magari inawajibika kwao. Anza chini — mwendeshaji kwa 3, kikomo kiondolewe baada ya 50 — kisha kiongeze nchi yako inapojifunza ni nani anayefikisha.",
