  "tower.carrierPapers.hint": "Leseni ya usafirishaji ya kampuni ya magari na bima yake ya bidhaa zilizo safarini zinarekodiwa na kuonyeshwa kwenye skrini ya Hati vyovyote utakavyochagua hapa. Hili linaamua tu kile kuisha muda KUNACHOFANYA: ikitekelezwa, safari za kampuni ya magari zinaondolewa kwenye ubao na haiwezi kuuziwa kazi mpya hadi hati ihuishwe; isipotekelezwa, inabaki kuwa onyo ambalo mtu lazima alishughulikie. Safari ambazo tayari zinaendelea zinamalizwa kila mara. Kampuni nyingi za magari zilijiunga bila tarehe hizi — zirekodi kabla ya kutekeleza, la sivyo hakuna kitakachobadilika.",
