  "tower.admins.revealBody": "Hii ndiyo mara pekee linaonyeshwa. Likabidhi ana kwa ana au kupitia njia unayoiamini, na umwambie alibadilishe. Hakuna kitu hapa kinachoweza kulionyesha tena — seva inahifadhi tu alama yake iliyofichwa (hash).",
