  "tower.claims.title": "Madai ya uharibifu",
  "tower.claims.lede": "Dai linasubiri hapa tu pale kampuni iliyobeba kifurushi imetaja bima, na kwa hiyo inalipa kutoka kwenye hesabu zake yenyewe. La zamani zaidi kwanza. Kwingineko kote tatizo lililoripotiwa linaishia kwenye ripoti ya madai ya uharibifu, iliyoorodheshwa hapa chini.",
  "tower.claims.caveatLead": "Kila mwisho una sababu, pamoja na kukataa.",
  "tower.claims.caveat": "Mdai anaonyeshwa unachoandika. Mtu ambaye bidhaa zake zilifika zimevunjika anastahili maelezo hata pale asipostahili pesa.",
