  "tower.claims.noAwardWithoutCover": "Hakuna fidia inayoweza kutolewa: kampuni iliyobeba kifurushi hiki haijataja bima yoyote, na hailipi chochote kutoka kwenye hesabu zake yenyewe. Lifunge kama halikukubaliwa, pamoja na sababu, na umwelekeze mdai kwenye ripoti ya madai ya uharibifu.",
