  "tower.claims.decideBody": "Fidia ya hadi {max} inaweza kulipwa hapa. Zaidi ya hapo lazima ilipwe nje ya jukwaa — hilo ni mazungumzo, si nambari kubwa zaidi kwenye kisanduku hiki.",
