  "tower.claims.freightNoBooks": "HAKUNA KILICHOTOZWA kupitia mtandao — malipo ya usafirishaji yalifanywa kati ya mtumaji na msafirishaji. Kubali au kataa pamoja na sababu; hakuna fidia inayowezekana hapa.",
  "tower.claims.freightCovered": "Usafirishaji wa {amount} umetozwa na sisi — kampuni iliyoutoza inataja bima hadi {cover}",
  "tower.claims.freightBilled": "Usafirishaji wa {amount} umetozwa na sisi, lakini kampuni iliyoutoza HAIJATAJA bima — hakuna fidia inayoweza kutolewa; hati ya mzigo ndiyo ripoti",
  "tower.claims.freightNoAward": "Hakuna aliyetozwa kwa mzigo huu kupitia mtandao, kwa hiyo hakuna chanzo cha kutoa fidia. Likubali pamoja na sababu inayosema kwamba pesa ni kati ya mtumaji na msafirishaji, au likatae.",
  "tower.claims.freightDecideBodyNoBooks": "Mtandao haukutoza chochote kwa mzigo huu, kwa hiyo hakuna pesa inayoweza kutolewa kama fidia hapa. Kukubali kunarekodi kwamba mtumaji alikuwa sahihi na kwamba malipo ya usafirishaji ni yake na ya msafirishaji kuyamaliza; mtumaji anaonyeshwa sababu yako kwa vyovyote vile.",
  "tower.disposal.title": "Vinasubiri kuondolewa",
  "tower.disposal.lede": "Vifurushi ambavyo mpokeaji aliviacha na mtumaji halipi ili kuvirudisha. Vya zamani zaidi kwanza: kila kimoja ni sanduku halisi katika duka halisi, kwenye nafasi ambayo duka hilo haliwezi kuitumia.",
  "tower.disposal.caveatLead": "Kinachotokea kwavyo ni sheria ya mahali hapo, si mpangilio.",
  "tower.disposal.caveat": "Mtandao huu hauigi sheria ya kuondoa bidhaa ambayo hauijui. Unakuonyesha orodha na gharama ya kufunga kimoja, nawe unatumia sheria ambayo eneo lako la kisheria linayo kweli.",
  "tower.disposal.count": "{n} vinasubiri",
