  "tower.disposal.closeBody": "Hili linalipa duka {amount} kwa nafasi ambayo limekuwa likishikilia na linarudisha nafasi hiyo. Mtandao unabeba gharama hiyo — hakuna mwingine atakayeibeba, na upungufu unaomwangukia kimya kimya mwenye duka aliyefanya kazi ndilo jambo moja ambalo mtandao huu unalikataa kila mahali pengine.",
