  "tower.fleets.title": "Kampuni za magari",
  "tower.fleets.count": "Kwenye mtandao: {n} · zinazokusubiri: {waiting}",
  "tower.fleets.lede": "Kampuni ya magari hujisajili yenyewe kwenye ukurasa wa mbele kwa hati zake nne, na mmoja wetu anaziangalia. Au isajili hapa: weka hati zake kwenye rekodi, na mfanyakazi mwenzako anaziangalia. Kwa njia yoyote ile, rekodi dhamana yake ili iwe hai — kisha watu wake wanaingia kwa nambari zao za simu na PIN zao wenyewe.",
  "tower.fleets.signedUp": "Ilijisajili yenyewe {date}",
  "tower.fleets.loading": "Inasoma kampuni za magari…",
  "tower.fleets.none": "Bado hakuna kampuni ya magari iliyosajiliwa.",
  "tower.fleets.newTitle": "Sajili kampuni ya magari",
  "tower.fleets.newHint": "Kampuni, bohari lake, mmiliki wake na nambari zake tatu",
  "tower.fleets.noCountry": "Bado hakuna nchi iliyowashwa, kwa hiyo kampuni ya magari haiwezi kusajiliwa. Washa moja chini ya “Tunapofanya kazi” kwanza.",
  "tower.fleets.newPhoneHint": "Nambari ya simu ndiyo ambayo meneja wa kwanza wa kampuni ya magari anaingia nayo: msimbo unatumwa kwake kwa SMS na anachagua PIN yake mwenyewe, kwa hiyo lazima iwe simu anayoishika. Jina la mmiliki na nambari yake ya ID vinaenda kwenye hifadhi salama ya utambulisho na havionyeshwi tena.",
