  "tower.fleets.papersHint": "Picha au nakala iliyochanganuliwa ya kila moja kati ya hizo nne. Anayeziweka kwenye rekodi si yule anayeziidhinisha: mfanyakazi mwenzake ndiye anayeziangalia baadaye.",
