  "tower.fleets.bondHint": "Dhamana ya uendeshaji ya kampuni ya magari ikishapokelewa, irekodi hapa. Hilo linaifanya kampuni ya magari kuwa hai na kuipa msimbo wake.",
  "tower.fleets.recordBond": "Rekodi dhamana",
  "tower.fleets.bondRecorded": "Kampuni ya magari iko hai. Ipe ofisi yake msimbo unaoonyeshwa kwenye mstari wake.",
  "tower.fleets.codeIs": "Msimbo wake ni",
  "tower.fleets.codeHint": "upe kwa ofisi ya kampuni ya magari. Kwenye programu ya Fleet wanauweka na kugusa “Umesahau PIN yako?”: msimbo unatumwa kwa SMS kwa nambari ya simu iliyo juu, wanaongeza barua pepe ya kurejesha akaunti, na wanachagua PIN yao wenyewe.",
  "tower.reports.notes": "{count, plural, one {Maelezo # ambayo mpokeaji aliongeza} other {Maelezo # ambayo mpokeaji aliongeza}} baada ya makabidhiano.",
  "tower.drivers.title": "Maombi ya madereva",
  "tower.drivers.lede": "Madereva wa rejista kamili wanaotusubiri — wajumbe wapya, na madereva wasio wa kampuni ya magari wanaoomba kujiendeshea wenyewe. Kinachoamuliwa ni kama mtu huyu anaweza kuendesha kisheria, kwa hiyo leseni aliyotuma inaonyeshwa kwenye mstari badala ya kufichwa nyuma ya mguso.",
  "tower.drivers.asks": "Si wa kampuni ya magari, anaomba kujiendeshea mwenyewe: {vehicle} {plate}, anaishi {country}. Kuidhinisha kunamfanya kuwa mjumbe akiwa na gari hilo; ukaguzi wa rekodi ni wako kuuwekea alama.",
  "tower.drivers.askApproved": "Ameidhinishwa — sasa anajiendeshea mwenyewe, kwa gari lake mwenyewe. Anaambiwa kwenye simu yake.",
  "tower.drivers.askRefused": "Amekataliwa — anaonyeshwa sababu yako, anabaki bila kampuni ya magari, na anaweza kuomba tena.",
  "tower.drivers.count": "wanaosubiri: {n}",
  "tower.drivers.loading": "Inasoma foleni…",
  "tower.drivers.none": "Hakuna dereva anayesubiri kuhakikiwa.",
  "tower.drivers.col.driver": "Dereva",
  "tower.drivers.col.licence": "Leseni",
  "tower.drivers.col.papers": "Hati",
  "tower.drivers.sent": "ilitumwa {date}",
  "tower.drivers.noPapers": "Bado hakuna kilichotumwa",
  "tower.drivers.recordNotClear": "ukaguzi wa rekodi ya uhalifu haujapitishwa",
  "tower.drivers.recordCleared": "Nimepitisha ukaguzi wa rekodi ya uhalifu",
  "tower.drivers.whatTheySent": "Alichotuma — leseni kwanza, kisha ID. Gusa moja ili uione kwa ukubwa kamili.",
  "tower.drivers.nothingToSee": "Hakuna picha za nyaraka zilizohifadhiwa kwa dereva huyu, kwa hiyo hakuna cha kukagua hapa. Kuidhinisha kunamaanisha kuidhinisha kwa nambari ya leseni na tarehe ya kuisha muda zilizoandikwa tu — sema hivyo kwenye maelezo yako ukifanya hivyo.",
  "tower.drivers.whyLabel": "Kwa nini unakataa hati hizi?",
  "tower.drivers.approved": "Dereva ameidhinishwa — beji yake imetolewa.",
  "tower.drivers.refused": "Amekataliwa — dereva anaonyeshwa sababu yako na anaweza kutuma hati mpya.",
  "tower.hubs.title": "Maombi ya vituo",
  "tower.hubs.lede": "Vituo vilivyojisajili vyenyewe na kutuma hati zake. Hadi kituo kiidhinishwe hakipangi chochote na hakuna kinachoelekezwa kwake. Kinachoamuliwa ni kama hapa ni mahali halisi, penye leseni ya biashara, panapoendeshwa na mtu aliye kwenye ID — kwa hiyo hati ziko kwenye mstari.",
  "tower.hubs.count": "vinavyosubiri: {n}",
  "tower.hubs.loading": "Inasoma foleni…",
