  "tower.hubs.col.papers": "Hati",
  "tower.hubs.sent": "ilitumwa {date}",
  "tower.hubs.whatTheySent": "Walichotuma — leseni kwanza, kisha ID, kisha eneo la biashara. Gusa moja ili uione kwa ukubwa kamili.",
  "tower.hubs.nothingToSee": "Hakuna picha zilizohifadhiwa kwa hati hizi, kwa hiyo hakuna cha kukagua hapa.",
  "tower.hubs.whyLabel": "Kwa nini unakataa hati hizi?",
  "tower.hubs.approved": "Kituo kimeidhinishwa — kinaweza kupokea mifuko na kupanga kuanzia sasa. Kimeambiwa.",
  "tower.hubs.refused": "Kimekataliwa — kituo kinaonyeshwa sababu yako na kinaweza kutuma hati mpya.",
  "tower.papers.licenceProof": "Leseni aliyotuma. Kagua tarehe iliyo juu yake kabla ya kuandika moja.",
  "tower.papers.licenceNoProof": "Hakuna picha ya leseni hii iliyohifadhiwa, kwa hiyo tarehe iliyo hapa chini haiwezi kukaguliwa dhidi ya chochote. Kuirekodi kunamrudisha barabarani kwa kauli yako peke yako.",
  "tower.approvals.licencePhoto": "Leseni ya biashara waliyotuma",
  "tower.approvals.noLicencePhoto": "Hakuna picha ya leseni iliyohifadhiwa. Kataa, na uombe moja: tarehe yake haiwezi kusomwa kutoka kwenye chochote.",
