  "tower.interest.promise": "Kila mtu hapa aliahidiwa jambo moja tu na si jingine: kwamba tutawaandikia siku watakapoweza kujisajili katika nchi yao — tena siku itakapofunguliwa, ikiwa usajili ulitangulia — na kusema ilikuwa ipi kati ya hizo mbili. Kuidhinisha mabadiliko hapa chini kunatuma hilo, kwa kila mtu ambaye bado anasubiri katika nchi hiyo.",
