  "tower.langs.title": "Lugha",
  "tower.langs.lede": "Maneno yote ya programu, kwa Kiingereza, katika toleo la 1 kama lilivyoandikwa ndani ya programu, na katika toleo la 2 la nchi yako. Andika maneno yako mwenyewe pale toleo la 1 linaposomeka vibaya katika nchi yako, au liache toleo la 1 kama lilivyo. Toleo la 1 halibadilishwi kamwe, na kila hatua inahifadhiwa pamoja na aliyeifanya na lini; watu wa nchi yako husoma toleo lako la 2 kuanzia mara ijayo programu yao inapofunguliwa.",
