  "tower.docs.title": "Masharti na taarifa",
  "tower.docs.lede": "Kile kila mtu anachokubali anapojisajili: masharti ya matumizi, kinachotokea kwa data yake, na vidakuzi — maandishi ya jumla, na kile sheria ya nchi inachoongeza. Mabadiliko ni toleo jipya: mmoja wenu analiandika pamoja na maelezo yanayosema kilichobadilika, na mwingine tofauti analichapisha. Kila mtu linayemhusu anaambiwa kwenye programu yake. Kila toleo linahifadhiwa, na linaweza kusomwa na kulinganishwa.",
  "tower.docs.generalTitle": "Kwa kila mtu",
  "tower.docs.generalLede": "Maandishi ya jumla: kila mtu anayejisajili anakubali haya, katika kila nchi.",
  "tower.docs.countriesTitle": "Ya kila nchi yenyewe",
