  "tower.conn.title": "Miunganisho",
  "tower.conn.lede": "Kile seva hii imeunganishwa nacho: seva ya njia na mshauri kwa ajili ya mipango ya kampuni za magari, na barua pepe, push na SMS inayobeba msimbo kwa kila mtu. Vyote vinawekwa mahali seva inapoendeshwa. Hapa inasema kama kila kimoja kimewekwa, kama kinajibu, na kama kinachoandikwa hapa kinatoka kabisa.",
  "tower.conn.unread": "Hili halikuweza kusomwa. Jaribu tena baada ya muda mfupi.",
