  "tower.conn.tag.refused": "Ufunguo umekataliwa",
  "tower.conn.router.title": "Seva ya njia",
  "tower.conn.router.off": "Hakuna seva ya njia iliyowekwa, kwa hiyo mpango wa kila siku unafanywa kwa umbali uliokadiriwa: mistari iliyonyooka pamoja na nyongeza kwa ajili ya barabara. Kila mpango unaiambia hivyo ofisi iliyouandaa.",
  "tower.conn.router.invalid": "Kilichowekwa si anwani ya mtandao, kwa hiyo hakuna mpango unaoweza kukitumia. Mpango wa kila siku unafanywa kwa umbali uliokadiriwa, na unaiambia ofisi yake kwamba seva ya njia haikuweza kufikiwa.",
  "tower.conn.router.unasked": "Hakuna mpango ulioiuliza tangu seva hii ianze ({since}). Ikague sasa ili kuona kama inajibu.",
  "tower.conn.router.answered": "Mpango wa mwisho kuiuliza, saa {when}, ulijibiwa: umbali wa barabara kwa {n, plural, one {mahali #} other {maeneo #}} yake.",
  "tower.conn.router.failed": "Mpango wa mwisho kuiuliza, saa {when}, haukupata umbali wa barabara kwa {n, plural, one {mahali #} other {maeneo #}} yake: {why}. Ulifanywa kwa umbali uliokadiriwa, na ulisema hivyo.",
  "tower.conn.router.noReason": "hakuna sababu iliyotolewa",
  "tower.conn.router.where": "Inawekwa kwenye seva kama GLOS_ROUTER_URL: anwani ya seva ya njia inayolingana na OSRM, yako mwenyewe au ya mtu yeyote inayoitumia. GLOS_ROUTER_PROFILE na GLOS_ROUTER_MAX_POINTS ndizo nyingine mbili. Ni viwianishi tu vinavyotumwa kwake — hakuna oda, hakuna jina, hakuna anwani.",
  "tower.conn.fact.address": "Anwani",
  "tower.conn.fact.none": "Hakuna iliyowekwa",
  "tower.conn.fact.notAnAddress": "Imewekwa, na si anwani ya mtandao",
  "tower.conn.fact.profile": "Wasifu ulioombwa",
  "tower.conn.fact.most": "Maeneo mengi zaidi katika ombi moja",
  "tower.conn.fact.mostValue": "{n} — siku yenye zaidi inapangwa kwa makadirio",
  "tower.conn.fact.table": "Maduka na vituo kwa barabara",
  "tower.conn.fact.tableValue": "{n, plural, one {mahali #} other {mahali #}}, umbali wa kila pahali hadi pengine ulipimwa {when}",
  "tower.conn.fact.tableNone": "Umbali bado haujapimwa: safari, nyakati za kufika na malipo ya mifuko hutumia makadirio hadi upimwe",
  "tower.conn.check.cta": "Ikague sasa",
  "tower.conn.check.asking": "Inauliza…",
  "tower.conn.check.what": "Ukaguzi unauliza umbali wa barabara kati ya bohari ya kampuni ya magari na mahali palipo mbali kidogo nalo. Hakuna kinachohifadhiwa kutokana nao.",
  "tower.conn.check.ok": "Ilijibu kwa ms {ms}: km {km} kwa barabara kati ya maeneo mawili yaliyo umbali wa km {apart}, karibu na bohari ya {near}.",
  "tower.conn.check.odd": "Ilijibu kwa ms {ms} — ikiwa na km {km} kwa barabara kati ya maeneo mawili yaliyo umbali wa km {apart}, karibu na bohari ya {near}. Hiyo haiwezi kuwa barabara kati yake: huenda seva ina ramani ya nchi nyingine.",
  "tower.conn.check.noRoad": "Ilijibu kwa ms {ms}, na haijui barabara yoyote kati ya maeneo mawili yaliyo umbali wa km {apart} karibu na bohari ya {near}. Huenda seva ina ramani ya nchi nyingine.",
  "tower.conn.check.failed": "Haikujibu: {why}.",
  "tower.conn.check.at": "Ilikaguliwa {when}.",
  "tower.conn.adviser.title": "Mshauri",
  "tower.conn.adviser.off": "Hakuna ufunguo uliowekwa, kwa hiyo ofisi ya kampuni ya magari inayomuuliza mshauri inaambiwa kwamba hajawekwa. Mipango inafanywa vilevile: mshauri anaeleza mpango na anabadilisha kile kinachoombwa kutoka kwake, na mpango wenyewe haujawahi kumhitaji.",
  "tower.conn.adviser.unasked": "Hakuna ofisi iliyomuuliza tangu seva hii ianze ({since}). Hakaguliwi kutoka hapa: swali kwake ni swali linalolipiwa.",
  "tower.conn.adviser.answered": "Ofisi ya mwisho kumuuliza, saa {when}, ilijibiwa.",
  "tower.conn.adviser.refused": "Ofisi ya mwisho kumuuliza, saa {when}, iliambiwa kwamba mshauri hajawekwa: ufunguo uliowekwa kwenye seva hii ulikataliwa. Kagua ufunguo.",
  "tower.conn.adviser.busy": "Ofisi ya mwisho kumuuliza, saa {when}, iliambiwa kwamba ana shughuli nyingi: huduma ilikuwa ikipunguza maombi, au ilikuwa imelemewa. Hilo hupita lenyewe, na mpango ulitolewa vilevile.",
  "tower.conn.adviser.unreachable": "Ofisi ya mwisho kumuuliza, saa {when}, haikupata jibu: huduma haikuweza kufikiwa, au ilishindwa. Mpango ulitolewa vilevile.",
