  "tower.ids.retakeHint": "Zimefifia, mng’ao kwenye kadi, hakuna nambari ya kumbukumbu kwenye picha. Wanasoma hili, picha zao zinafutwa, na wanapata wiki nyingine.",
  "tower.ids.retakeCta": "Waombe wapige picha tena",
  "tower.ids.weighTitle": "Cha kupima",
  "tower.ids.note.holderSilent": "Aliye nayo hakutuma chochote katika wiki yake. Ikiwa kadi ya mdai ina nambari hiyo, ID inaweza kwenda kwake. Usajili wa aliye nayo basi unasimamishwa, haufutwi.",
  "tower.ids.note.claimantDiffers": "Kadi ya mdai mwenyewe ina nambari tofauti. Aliandika ya mtu mwingine alipojisajili: ID inabaki ilipo, na anajisajili kwa nambari iliyo kwenye kadi yake.",
  "tower.ids.note.holderDiffers": "Kadi ya aliye nayo mwenyewe ina nambari tofauti: yake iliandikwa vibaya. ID ikienda kwa mdai, rekodi ya aliye nayo inachukua nambari uliyosoma na hakuna anayesimamishwa.",
  "tower.ids.note.bothMatch": "Kadi zote mbili zina nambari hii, kwa hiyo mojawapo si halisi, na picha haiwezi kusema daima ni ipi. Linganisha kila uso na kadi yake, nambari ya kumbukumbu katika kila picha ya kwanza, na kile aliye nayo alichotuma alipojisajili. Ikiwa huwezi kujua, iache kwa aliye nayo na useme hivyo: asiyeipata anaweza kuja na kadi yenyewe.",
  "tower.ids.note.nothingOnRecord": "Aliye nayo hakutuma nakala ya ID alipojisajili, kwa hiyo hakuna kitu cha zamani zaidi cha kulinganisha picha zake nacho.",
  "tower.ids.sentBack": "Imerudishwa na {why}",
  "tower.ids.wait.opened": "Inasubiri picha za mdai. Aliye nayo bado hajaambiwa.",
  "tower.ids.wait.answering": "Aliye nayo ameambiwa na ana wiki moja kujibu. Inaweza kuamuliwa akishajibu, au wiki ikiisha.",
  "tower.ids.wait.appointment": "Miadi imewekwa. Kinachoonekana huko kinarekodiwa kuanzia siku hiyo.",
  "tower.ids.over": "Hakuna kilichobaki cha kuamua hapa.",
  "tower.ids.proposeLede": "Soma nambari iliyo kwenye kila kadi kwanza. Kisha sema ID ni ya nani. Hakuna kinachobadilika hadi mfanyakazi wa pili aidhinishe.",
  "tower.ids.recordLede": "Siku ya miadi imefika. Sema nani alikuja, soma nambari iliyo kwenye kila kadi uliyoonyeshwa, na useme ID ni ya nani. Mfanyakazi wa pili anaidhinisha, na huo ni uamuzi wa mwisho.",
  "tower.ids.whoCame": "Nani alikuja",
  "tower.ids.came.claimant": "Aliyekataliwa alikuja, na kadi yake",
