  "tower.ids.cannot.holderCard": "Aliye nayo hajaonyesha kadi yenye nambari hii, na kadi ya mdai haijasomwa kuwa na nambari tofauti. Soma kadi kwanza.",
  "tower.ids.cannot.notCame": "Uamuzi unaweza kubadilika tu kwa mtu aliyekuja na kadi yake.",
  "tower.ids.means.claimant": "ID inahifadhiwa kwa aliyekataliwa hadi atakapojisajili. Usajili wa aliye nayo unasimamishwa: anamaliza alicho nacho mkononi na haanzi kitu kipya hadi ID yake mwenyewe iwe kwenye rekodi.",
  "tower.ids.means.claimantCorrected": "ID inahifadhiwa kwa aliyekataliwa hadi atakapojisajili. Rekodi ya aliye nayo inachukua nambari uliyosoma kwenye kadi yake mwenyewe, na hakuna kingine kinachobadilika kwake.",
  "tower.ids.means.holder": "Hakuna kinachobadilika kwa aliye nayo. Aliyekataliwa anaambiwa kwa nini, na bado anaweza kuweka miadi.",
  "tower.ids.what": "Ulichokagua, na jinsi gani",
  "tower.ids.whatHint": "Uso dhidi ya kadi, nambari ya kumbukumbu kwenye picha, kilicho kwenye rekodi. Mfanyakazi wa pili anaidhinisha kwa msingi wa hilo.",
