  "tower.catchments.lede": "Mtandao wa vituo: kila kituo kilichoidhinishwa kinahudumia chenyewe kanda kilipo, kituo kinaweza kuongeza kanda jirani kutoka programu yake, nawe unaongeza kituo kwenye kanda au kukiondoa — hata kanda kilipo. Kifurushi kinaenda kwenye kituo cha kanda yake kilicho karibu zaidi na duka lake chenye nafasi sakafuni. Kanda isiyo na kituo inapangiwa njia kama hapo awali, kwa jina la eneo ambalo maduka yake yaliandika; kanda iliyounganishwa au kugawanywa tangu hapo inabaki na vituo vilivyoongezwa kwenye kanda ambayo ilitokana nayo hadi iwe na vyake.",
